import manifest from '../../data/hero-layers.json';

/** Real-UI hero layers, generated by scripts/build-hero-layers.ts from committed screenshots. */
export type HeroWindowName = keyof typeof manifest.windows;
export type HeroCropName = keyof typeof manifest.crops;

interface ThemedFiles {
  dark: string;
  light: string;
}

interface Size {
  width: number;
  height: number;
}

/**
 * Inline custom properties holding both theme variants of a layer. Hero styles turn the active
 * theme's variable into `background-image`, so a visitor only downloads the images they see.
 */
export function themedImage(files: ThemedFiles, size?: Size): string {
  const style = [`--img-dark:url(${files.dark})`, `--img-light:url(${files.light})`];
  if (size) style.push(`aspect-ratio:${size.width} / ${size.height}`);
  return style.join(';');
}

export const heroWindow = (name: HeroWindowName) => manifest.windows[name];
export const heroCrop = (name: HeroCropName) => manifest.crops[name];
